package com.sanctuarygames.createtransit.radio;
import com.sanctuarygames.createtransit.CreateTransit;import net.minecraft.core.registries.Registries;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.BlockBehaviour;import net.minecraft.world.level.block.entity.BlockEntityType;import net.minecraft.world.inventory.MenuType;import net.minecraft.world.item.*;import net.neoforged.neoforge.registries.*;import net.neoforged.bus.api.IEventBus;import net.neoforged.neoforge.common.extensions.IMenuTypeExtension;
public final class RadioRegistry {
 public static final DeferredRegister.Blocks BLOCKS=DeferredRegister.createBlocks(CreateTransit.MOD_ID);public static final DeferredRegister.Items ITEMS=DeferredRegister.createItems(CreateTransit.MOD_ID);public static final DeferredRegister<BlockEntityType<?>> TYPES=DeferredRegister.create(Registries.BLOCK_ENTITY_TYPE,CreateTransit.MOD_ID);public static final DeferredRegister<MenuType<?>> MENUS=DeferredRegister.create(Registries.MENU,CreateTransit.MOD_ID);
 public static final DeferredBlock<StationSpeakerBlock> SPEAKER=BLOCKS.registerBlock("station_speaker",StationSpeakerBlock::new,BlockBehaviour.Properties.of().strength(1.5f).noOcclusion().sound(SoundType.METAL));
 public static final DeferredItem<BlockItem> SPEAKER_ITEM=ITEMS.registerSimpleBlockItem(SPEAKER);
 public static final DeferredBlock<StationSpeakerBlock> CEILING=BLOCKS.registerBlock("ceiling_speaker",p->new StationSpeakerBlock(p,"ceiling"),BlockBehaviour.Properties.of().strength(1.5f).noOcclusion().sound(SoundType.METAL)),COLUMN=BLOCKS.registerBlock("column_speaker",p->new StationSpeakerBlock(p,"column"),BlockBehaviour.Properties.of().strength(1.5f).noOcclusion().sound(SoundType.METAL)),HORN=BLOCKS.registerBlock("horn_speaker",p->new StationSpeakerBlock(p,"horn"),BlockBehaviour.Properties.of().strength(1.5f).noOcclusion().sound(SoundType.METAL));
 public static final DeferredItem<BlockItem> CEILING_ITEM=ITEMS.registerSimpleBlockItem(CEILING),COLUMN_ITEM=ITEMS.registerSimpleBlockItem(COLUMN),HORN_ITEM=ITEMS.registerSimpleBlockItem(HORN);
 public static final DeferredHolder<BlockEntityType<?>,BlockEntityType<StationSpeakerEntity>> SPEAKER_ENTITY=TYPES.register("station_speaker",()->BlockEntityType.Builder.of(StationSpeakerEntity::new,SPEAKER.get(),CEILING.get(),COLUMN.get(),HORN.get()).build(null));
 public static final DeferredHolder<MenuType<?>,MenuType<SpeakerMenu>> SPEAKER_MENU=MENUS.register("station_speaker",()->IMenuTypeExtension.create(SpeakerMenu::new));
 public static void register(IEventBus b){BLOCKS.register(b);ITEMS.register(b);TYPES.register(b);MENUS.register(b);b.addListener(RadioNetwork::register);}
}
